import sys
p=sys.argv[1]; t=open(p,encoding='utf-8').read()
def rep(old,new,n=1):
    global t
    assert t.count(old)==n,(old[:60],t.count(old)); t=t.replace(old,new)
def after(anchor_start,new_pars):
    global t
    ps=t.split('\n\n'); idx=[i for i,x in enumerate(ps) if x.startswith(anchor_start)]
    assert len(idx)==1,(anchor_start,len(idx)); i=idx[0]
    ps[i+1:i+1]=new_pars; t='\n\n'.join(ps)
# 1. Zaratiegui
rep('La definición termina donde termina el servicio prestado: en alguien que recibe.','La definición termina donde termina el producto: en alguien que lo recibe.')
